    if (left == null) {
        return node; // cannot rotate if there is no left child
    }
    // Detach left.right from left
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    // Move node down to the right of left
    left.right = node;
    // Update parent references
