public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    // Recursive helper to register deleteOnExit on each file/directory
    class Deleter implements Runnable {
        private final File f;
        Deleter(File f){this.f=f;}
        @Override
        public void run() {
            // no operation needed; deletion handled by deleteOnExit
        }
    }
    // Register deleteOnExit for all files and directories
    java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File cur = stack.pop();
        if (cur.isDirectory()) {
            File[] children = cur.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
        if (!cur.deleteOnExit()) {
            // If register failed, attempt immediate deletion; if it fails throw
            if (!cur.delete()) {
                throw new IOException("Failed to schedule or delete " + cur);
            }
        }
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) throw new NullPointerException("file is null");
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        java.util.ArrayDeque<File> stack = new java.util.ArrayDeque<>();
        stack.push(file);
        while (!stack.isEmpty()) {
            File current = stack.pop();
            if (current.isDirectory()) {
                File[] children = current.listFiles();
                if (children != null) {
                    for (File child : children) {
                        stack.push(child);
                    }
                }
            }
            if (!current.delete()) {
                throw new RuntimeException("Failed to delete " + current);
            }
        }
    }));
}

