@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Add all vertices to the graph
    for (V vertex : resultMap.values()){
        target.addVertex(vertex);
    }
    // Build a simple bipartite partition: first half vs second half of the vertices list
    List<V> vertices = new ArrayList<>(resultMap.values());
    int partitionSize = vertices.size() / 2;
    for (int i = 0; i < partitionSize; i++){
        for (int j = partitionSize; j < vertices.size(); j++){
            target.addEdge(vertices.get(i), vertices.get(j));
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Add all vertices to the graph
    for (V vertex : resultMap.values()){
        target.addVertex(vertex);
    }
    // Store vertices in order to create two partitions for the bipartite graph
    java.util.ArrayList<V> vertices = new java.util.ArrayList<>(resultMap.values());
    int total = vertices.size();
    if (total < 2) {
        return; // Not enough vertices to form a bipartite graph
    }
    int mid = total / 2;
    java.util.List<V> partLeft = vertices.subList(0, mid);
    java.util.List<V> partRight = vertices.subList(mid, total);
    // Connect each vertex in the left partition to every vertex in the right partition
    for (V u : partLeft) {
        for (V v : partRight) {
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    List<V> vertices = new ArrayList<>(resultMap.values());
    int size = vertices.size();
    if (size < 2) {
        return;
    }
    int mid = size / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, size);
    // Add all vertices to the graph
    for (V v : vertices) {
        target.addVertex(v);
    }
    // Add complete bipartite edges
    for (V u : left) {
        for (V w : right) {
            target.addEdge(u, w);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    List<V> left = new java.util.ArrayList<>();
    List<V> right = new java.util.ArrayList<>();
    for (java.util.Map.Entry<String, V> e : resultMap.entrySet()) {
        if (e.getKey().length() % 2 == 0) {
            left.add(e.getValue());
        } else {
            right.add(e.getValue());
        }
    }
    for (V v : left) {
        target.addVertex(v);
    }
    for (V v : right) {
        target.addVertex(v);
