        }
    }
}

@Override public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    Collection<V> vertexCollection = resultMap.values();
    if (vertexCollection == null || vertexCollection.isEmpty()) {
        return;
    }
    // Ensure all vertices are present in the target graph
    for (V v : vertexCollection) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Create a list of vertices to iterate over indices
    List<V> vertexList = new ArrayList<>(vertexCollection);
    int size = vertexList.size();
    for (int i = 0; i < size; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = vertexList.get(j);
            // Add an edge between distinct vertices if not already present
            if (!target.containsEdge(v1, v2)) {
                target.addEdge(v1, v2);
            }
        }
    }
}

