public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate serialized size using the provided schema
    int messageSize = schema.getSerializedSize(message);

    // Write the message size as a varint prefix to the output stream
    int size = messageSize;
    do {
        if ((size & ~0x7F) == 0) {
            out.write(size);
            break;
        } else {
            out.write((size & 0x7F) | 0x80);
            size >>>= 7;
        }
    } while (true);

    // Write the actual serialized message
    schema.writeTo(out, message);
    out.flush();
    return messageSize;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message, buffer);
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    schema.writeTo(message, cos, buffer);
    cos.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.getCachedSize(message);
    CodedOutputStream cos = CodedOutputStream.newInstance(buffer);
    cos.writeInt32NoTag(size);
    schema.writeTo(message, cos);
    buffer.writeTo(out);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Serialize the message into the buffer
    schema.writeTo(buffer, message);
    int size = buffer.currentSize();
    // Write the length as a varint
    int value = size;
    while ((value & ~0x7F) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
    // Write the serialized bytes
    byte[] bytes = buffer.getBuffer();
    out.write(bytes, 0, size);
    // Reset the buffer for potential reuse
    buffer.reset();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    // write the size prefix (big-endian)
    out.write((byte)(size >>> 24));
    out.write((byte)(size >>> 16));
    out.write((byte)(size >>> 8));
    out.write((byte)size);
    // serialize the message into the buffer
    buffer.clear();
    schema.writeTo(message, buffer);
    // write the serialized bytes to the stream
    byte[] buf = buffer.getByteArray();
    out.write(buf, 0, size);
    return size;
}

