Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the table (assumed to be provided by a helper method)
    Mappings currentMappings = getCurrentMappingsFromIndex(tableName);
    // Create a container for the diff result
    Mappings diff = new Mappings();
    // Obtain the field maps from both mappings (assuming getFields() returns a Map<String, Object>)
    Map<String, Object> currentFields = currentMappings.getFields();
    Map<String, Object> inputFields = mappings.getFields();
    // Iterate over current fields and collect those missing in input mapping
    for (Map.Entry<String, Object> entry : currentFields.entrySet()) {
        String fieldName = entry.getKey();
        // Skip the special _source field to avoid update conflicts
        if ("_source".equals(fieldName)) {
            continue;
        }
        if (!inputFields.containsKey(fieldName)) {
            // Assume diff has an addField method to add a field definition
            diff.addField(fieldName, entry.getValue());
        }
    }
    return diff;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mappings for the specified table
    Mappings current = getCurrentMappings(tableName);

    // Maps that hold the properties of the current and the input mappings
    Map<String, Object> curProps = current.getProperties();
    Map<String, Object> inpProps = mappings.getProperties();

    // Prepare a map for the diff result, skipping the "_source" configuration
    Map<String, Object> diffProps = new HashMap<>();
    for (Map.Entry<String, Object> entry : curProps.entrySet()) {
        String key = entry.getKey();
        if ("_source".equals(key)) {
            continue; // skip _source config to avoid current index update conflict
        }
        if (!inpProps.containsKey(key)) {
            diffProps.put(key, entry.getValue());
        }
    }

    // Construct the diff mapping
    Mappings diff = new Mappings();
    diff.setProperties(diffProps);
    return diff;
}

