    Map<String, Object> currentProps = current.getProperties();
    Map<String, Object> inputProps = mappings != null ? mappings.getProperties() : java.util.Collections.emptyMap();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String key = entry.getKey();
        if ("_source".equals(key) || inputProps.containsKey(key)) {
