protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long duration = FETCH_DATA_DURATION;
    long curr = start;
    while (curr < end) {
        long next = Math.min(curr + duration, end);
        ranges.add(new TimeRange(curr, next));
        curr = next;
    }
    return ranges;
}

