public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        int cp = Character.codePointAt(str, i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

