public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int end = index + len;
    int byteCount = 0;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        // Handle surrogate pairs for code points > 0xFFFF
        if (c >= '\uD800' && c <= '\uDBFF' && (i + 1) < end) {
            char c2 = str.charAt(i + 1);
            if (c2 >= '\uDC00' && c2 <= '\uDFFF') {
                // Valid surrogate pair -> 4-byte UTF-8
                byteCount += 4;
                i++; // Skip low surrogate
                continue;
            }
        }
        if (c <= 0x7F) {
            byteCount += 1;
        } else if (c <= 0x7FF) {
            byteCount += 2;
        } else {
            byteCount += 3;
        }
    }
    return byteCount;
}

