        if (codePoint <= 0x7F) {
            utf8Length += 1;
        } else if (codePoint <= 0x7FF) {
            utf8Length += 2;
        } else if (codePoint <= 0xFFFF) {
            utf8Length += 3;
        } else {
            utf8Length += 4;
        }
    }
    return utf8Length;
}

