            String propVal = props.getProperty(propKey);
            if (propVal == null) {
                propVal = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(propVal));
        }
        matcher.appendTail(sb);
        result = sb.toString();
    }
    return result;
}

