public static List<PathSegmentImpl> decodePath(URI u,boolean decode){  
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();  
    if (u == null) return segments;  
    String rawPath = u.getRawPath();  
    if (rawPath == null || rawPath.isEmpty()) return segments;  
    int start = 0;  
    if (rawPath.charAt(0) == '/') start = 1;  
    String path = rawPath.substring(start);  
    if (path.isEmpty()) return segments;  
    String[] parts = path.split("/");  
    for (String part : parts) {  
        if (part.isEmpty()) continue;  
        String seg;  
        if (decode) {  
            try {  
                seg = java.net.URLDecoder.decode(part, "UTF-8");  
            } catch (java.io.UnsupportedEncodingException e) {  
                throw new java.lang.RuntimeException(e);  
            }  
        } else {  
            seg = part;  
        }  
        segments.add(new PathSegmentImpl(seg));  
    }  
    return segments;  
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present, as it's not a delimiter
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' to get raw segments
    String[] parts = path.split("/", -1); // keep empty parts
    for (String part : parts) {
        if (part.isEmpty()) {
            // Skip empty segments caused by leading or consecutive slashes
            continue;
        }
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed, rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(value, "UTF-8");
            } catch (Exception e) {
                // ignore decoding errors and keep the raw value
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    // Remove leading '/' if present
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return result;
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue; // skip empty segments
        }
        String decoded = segment;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(segment, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, keep the original segment
            }
        }
        result.add(new PathSegmentImpl(decoded));
    }
    return result;
}

public static java.util.List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    if (path.startsWith("/")) {
        if (path.length() == 1) {
            return segments;
        }
        path = path.substring(1);
    }
    int start = 0;
    int idx;
    while ((idx = path.indexOf('/', start)) != -1) {
        String enc = path.substring(start, idx);
        String seg = decode ? java.net.URLDecoder.decode(enc, java.nio.charset.StandardCharsets.UTF_8) : enc;
        segments.add(new PathSegmentImpl(seg));
        start = idx + 1;
    }
    String enc = path.substring(start);
    if (!enc.isEmpty()) {
        String seg = decode ? java.net.URLDecoder.decode(enc, java.nio.charset.StandardCharsets.UTF_8) : enc;
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

