private void pop(final String descriptor) {
    if (descriptor.charAt(0) == '(') {
        for (int i = 1; descriptor.charAt(i) != ')'; ) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // reference type; consume until ';'
                while (descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
            } else if (c == '[') {
                // array: consume all '[' then base type
                while (descriptor.charAt(i) == '[') i++;
                if (descriptor.charAt(i) == 'L') {
                    while (descriptor.charAt(i) != ';') i++;
                    i++; // skip ';'
                } else {
                    i++; // primitive base type
                }
            } else {
                // primitive type
                i++;
            }
            // pop one abstract type from the output frame stack
            outputFrame.pop();
        }
    } else {
        // Single type descriptor
        int i = 0;
        char c = descriptor.charAt(i);
        if (c == 'L') {
            while (descriptor.charAt(i) != ';') i++;
            i++; // skip ';'
        } else if (c == '[') {
            while (descriptor.charAt(i) == '[') i++;
            if (descriptor.charAt(i) == 'L') {
                while (descriptor.charAt(i) != ';') i++;
                i++; // skip ';'
            } else {
                i++; // primitive base type
            }
        } else {
            i++; // primitive type
        }
        outputFrame.pop();
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    // If descriptor is a method, pop only argument types
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Skip current argument type
            int start = i;
            char c = descriptor.charAt(i);
            if (c == '[') {
                // Skip all '['
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now at element type
                if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                    // Reference type: skip until ';'
                    i++;
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // Skip ';'
                } else if (i < descriptor.length()) {
                    // Primitive type: single char
                    i++;
                }
            } else if (c == 'L') {
                // Reference type: skip until ';'
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // Skip ';'
            } else {
                // Primitive type: single char
                i++;
            }
            // One argument popped
            count++;
        }
        // Return type is ignored; no further action needed
    } else {
        // Descriptor represents a single type (non-method)
        count = 1;
    }
    for (int j = 0; j < count; j++) {
        outputStack.pop();
    }
}

private void pop(final String descriptor){
    int count = 0;
    if (descriptor.charAt(0) == '('){
        int end = descriptor.indexOf(')', 1);
        int pos = 1;
        while (pos < end){
            // skip array dimensions
            while (descriptor.charAt(pos) == '['){ pos++; }
            // base type
            char type = descriptor.charAt(pos);
            if (type == 'L'){
                pos = descriptor.indexOf(';', pos) + 1;
            } else {
                pos++;
            }
            count++;
        }
    } else {
        if (!descriptor.equals("V")){
            count = 1;
        }
    }
    for (int i = 0; i < count; i++){
        stack.pop();
    }
}

private void pop(final String descriptor){
    int pos = 0;
    // If the descriptor represents a method, skip the leading '('
    if (descriptor.charAt(0) == '('){
        pos = 1;
        // Process all argument types until we encounter ')'
        while (descriptor.charAt(pos) != ')'){
            int len = typeDescriptorLength(descriptor, pos);
            // Remove one element from the output frame stack for each argument type
            outputFrameStack.remove(outputFrameStack.size() - 1);
            pos += len;
        }
    } else {
        // The descriptor itself is a type; pop one element
        int len = typeDescriptorLength(descriptor, pos);
        outputFrameStack.remove(outputFrameStack.size() - 1);
        pos += len;
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int index = 0;
    // Method descriptor
    if (descriptor.charAt(0) == '('){
        index = 1;
        while (index < descriptor.length() && descriptor.charAt(index) != ')'){
            int end = index;
            // consume array brackets
            while (descriptor.charAt(end) == '['){
                end++;
            }
            // consume reference type
            if (descriptor.charAt(end) == 'L'){
                end++;
                while (descriptor.charAt(end) != ';'){
                    end++;
                }
            }
            // pop a single type from the output frame stack
            outputStack.pop();
            // move to the next type descriptor
            index = end + 1;
        }
    } else { // descriptor is a single type descriptor
        int end = 0;
        // consume array brackets
        while (descriptor.charAt(end) == '['){
            end++;
        }
        // consume reference type
        if (descriptor.charAt(end) == 'L'){
            end++;
            while (descriptor.charAt(end) != ';'){
                end++;
            }
        }
        outputStack.pop();
    }
}

