public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Retrieve the buffer for the current node
        byte[] buf = node.getBuffer();
        // The number of valid bytes in this buffer
        int len = node.getSize();
        // Write the bytes to the DataOutput
        out.write(buf, 0, len);
        // Accumulate total size written
        totalSize += len;
        // Move to the next node in the linked buffer
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buffer = current.getBuffer();      // obtain the backing byte array
        int offset = current.getOffset();         // starting offset within the buffer
        int length = current.getSize();           // number of bytes to write
        out.write(buffer, offset, length);
        totalSize += length;
        current = current.getNext();              // move to the next linked buffer node
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int size = node.getCount();
    out.write(node.getData(), 0, size);
    return size;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer curr = node;
    while (curr != null) {
        int start = curr.getStart();
        int end = curr.getEnd();
        byte[] buf = curr.getBuffer();
        int len = end - start;
        if (len > 0) {
            out.write(buf, start, len);
            totalSize += len;
        }
        curr = curr.getNext();
    }
    return totalSize;
}

