private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Object type = currentFrame[i];
        if (type == null) {
            // Top_variable_info
            stackMapTableEntries.putU1(0);
        } else if (type instanceof Integer) {
            // Integer_variable_info
            stackMapTableEntries.putU1(1);
        } else if (type instanceof Float) {
            // Float_variable_info
            stackMapTableEntries.putU1(2);
        } else if (type instanceof Long) {
            // Long_variable_info
            stackMapTableEntries.putU1(3);
        } else if (type instanceof Double) {
            // Double_variable_info
            stackMapTableEntries.putU1(4);
        } else if (type instanceof String) {
            // Object_variable_info – constant‑pool reference
            stackMapTableEntries.putU1(7);
            int cpIndex = constantPool.getIndex((String) type);
            stackMapTableEntries.putU2(cpIndex);
        } else if (type instanceof Uninitialized) {
            // Uninitialized_variable_info – offset of the new instruction
            stackMapTableEntries.putU1(8);
            int offset = ((Uninitialized) type).getOffset();
            stackMapTableEntries.putU2(offset);
        } else if (type instanceof UninitializedThisToken) {
            // Uninitialized_this_variable_info
            stackMapTableEntries.putU1(6);
        } else {
            // Default to Top_variable_info if type is unknown
            stackMapTableEntries.putU1(0);
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    for(int i=start;i<end;i++){
        String type = currentFrame[i];
        int tag;
        switch(type){
            case "top":
                tag = 0;
                break;
            case "int":
                tag = 1;
                break;
            case "float":
                tag = 2;
                break;
            case "double":
                tag = 3;
                break;
            case "long":
                tag = 4;
                break;
            case "null":
                tag = 5;
                break;
            case "uninitialized":
                tag = 7;
                break;
            default: // assume annotation or class reference
                tag = 6;
                break;
        }
        stackMapTableEntries.add(tag);
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        VerificationType vt = currentFrame[i];
        switch (vt.getTag()) {
            case VerificationType.TOP:
            case VerificationType.INTEGER:
            case VerificationType.FLOAT:
            case VerificationType.LONG:
            case VerificationType.DOUBLE:
            case VerificationType.NULL:
            case VerificationType.UNINITIALIZED_THIS:
                stackMapTableEntries.putByte((byte) vt.getTag());
                break;
            case VerificationType.OBJECT:
                stackMapTableEntries.putByte((byte) vt.getTag());
                stackMapTableEntries.putShort(((ReferenceType) vt).getCPInfoIndex());
