            case VerificationType.UNINITIALIZED:
                stackMapTableEntries.putByte((byte) vt.getTag());
                stackMapTableEntries.putShort(((UninitializedType) vt).getOffset());
                break;
            default:
                throw new IllegalArgumentException("Unknown verification type: " + vt.getTag());
        }
    }
