                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '\"':
                        sb.append('\"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case 'u':
                        if (i + 6 > len) {
                            throw new Exception("Invalid Unicode escape sequence at position " + i);
                        }
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int codePoint = Integer.parseInt(hex, 16);
                            sb.append((char) codePoint);
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                        }
                        i += 6;
                        continue;
                    default:
                        // If not a recognized escape, keep literal characters
                        sb.append('\\');
                        sb.append(next);
                        break;
                }
                i += 2;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

