            case 9:  // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
    }
    int tag = buf[offset++] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    int length = ((buf[offset] & 0xFF) << 8) | (buf[offset + 1] & 0xFF);
    offset += 2;
    byte[] utfBytes = new byte[length];
    System.arraycopy(buf, offset, utfBytes, 0, length);
    String result = new String(utfBytes, java.nio.charset.StandardCharsets.UTF_8);
    int charsNeeded = result.length();
    if (charBuffer.length < charsNeeded) {
        throw new IllegalArgumentException("Provided character buffer is too small");
    }
    result.getChars(0, charsNeeded, charBuffer, 0);
    return result;
}

