final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int length = ((classFileBuffer[constantPoolEntryIndex + 1] & 0xFF) << 8) |
                  (classFileBuffer[constantPoolEntryIndex + 2] & 0xFF);
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small");
    }
    java.nio.charset.CharsetDecoder decoder =
        java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer,
                                                           constantPoolEntryIndex + 3,
                                                           length);
    java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
    decoder.decode(byteBuf, charBuf, true);
    int charsRead = charBuf.position();
    charBuf.clear();
