                    | (classFileBuffer[entryOffset + 2] & 0xFF);
    if (utfLength > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 string");
    }
    // Extract the UTF-8 bytes
    int strStart = entryOffset + 3;
    byte[] utfBytes = new byte[utfLength];
