    int requiredSize = this.used + byteLength;
    if (buffer.length < requiredSize) {
        int newSize = Math.max(buffer.length * 2, requiredSize);
        this.buffer = java.util.Arrays.copyOf(this.buffer, newSize);
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(this.buffer, this.used, this.used + byteLength, (byte)0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.used, byteLength);
    }
    this.used += byteLength;
    return this;
}

