    if (byteLength <= 0) {
        return this;
    }
    int newCapacity = this.size + byteLength;
    if (newCapacity > this.buffer.length) {
        int expandedCap = Math.max(newCapacity, this.buffer.length * 2);
        byte[] tmp = new byte[expandedCap];
        System.arraycopy(this.buffer, 0, tmp, 0, this.size);
        this.buffer = tmp;
    }
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.buffer[this.size + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.size, byteLength);
    }
    this.size += byteLength;
    return this;
}

