protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    E firstEdge = edgeList.get(0);
    V start = graph.getEdgeSource(firstEdge);
    vertexList.add(start);
    V current = start;
    for (E e : edgeList) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        V next;
        if (source.equals(current)) {
            next = target;
        } else if (target.equals(current)) {
            next = source;
        } else {
            next = target;
        }
        vertexList.add(next);
        current = next;
    }
    V end = vertexList.get(vertexList.size() - 1);
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, start, end, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    java.util.List<E> edgeList = new java.util.ArrayList<E>(tour);
    return new org.jgrapht.graph.DefaultGraphPath<V,E>(graph, null, null, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour.isEmpty()){
        return null;
    }
    List<E> ordered = new ArrayList<>();
    List<E> remaining = new ArrayList<>(tour);
    // pick an arbitrary starting edge
    E start = remaining.remove(0);
    ordered.add(start);
    V prev = graph.getEdgeTarget(start);
    double weight = graph.getEdgeWeight(start);
    // build the ordered edge sequence
    while (!remaining.isEmpty()){
        Iterator<E> it = remaining.iterator();
        boolean found = false;
        while (it.hasNext()){
            E e = it.next();
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            if (s.equals(prev)){
                ordered.add(e);
                prev = t;
                weight += graph.getEdgeWeight(e);
                it.remove();
                found = true;
                break;
            }else if (t.equals(prev)){
                ordered.add(e);
                prev = s;
                weight += graph.getEdgeWeight(e);
                it.remove();
                found = true;
                break;
            }
        }
        if (!found){
            break;
        }
    }
    // gather vertex list
    List<V> vertexList = new ArrayList<>();
    V current = graph.getEdgeSource(ordered.get(0));
    vertexList.add(current);
    for (E e : ordered){
        V next = current.equals(graph.getEdgeSource(e)) ?
                 graph.getEdgeTarget(e) :
                 graph.getEdgeSource(e);
        vertexList.add(next);
        current = next;
    }
    V source = vertexList.get(0);
    V target = vertexList.get(vertexList.size()-1);
    return new org.jgrapht.GraphPathImpl<>(vertexList, ordered, weight, source, target);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    List<E> edgeList = new java.util.ArrayList<>(tour);
    E first = edgeList.get(0);
    V source = graph.getEdgeSource(first);
    E last = edgeList.get(edgeList.size() - 1);
    V target = graph.getEdgeTarget(last);
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, source, target, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        return null;
    }
    // Convert the set of edges to a list to preserve a deterministic order
    java.util.List<E> edgeList = new java.util.ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        // No edges in the tour, return an empty path
        return new org.jgrapht.graph.GraphWalk<>(graph);
    }

    // Determine start and end vertices based on the edge ordering
    V start = graph.getEdgeSource(edgeList.get(0));
    V end = graph.getEdgeTarget(edgeList.get(0));
    for (int i = 1; i < edgeList.size(); i++) {
        E e = edgeList.get(i);
        end = graph.getEdgeTarget(e);
    }

    // Calculate the total weight of the path
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    // Construct a GraphWalk (which implements GraphPath) from the collected data
    return new org.jgrapht.graph.GraphWalk<>(graph, start, end, edgeList, totalWeight);
}

