private String unescapeId(String input){
    if (input == null) return null;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(++i);
            switch (next) {
                case 'a': sb.append('\u0007'); break; // alert
                case 'b': sb.append('\b'); break;       // backspace
                case 't': sb.append('\t'); break;       // horizontal tab
                case 'n': sb.append('\n'); break;       // line feed
                case 'r': sb.append('\r'); break;       // carriage return
                case 'f': sb.append('\f'); break;       // form feed
                case '\\': sb.append('\\'); break;      // backslash
                case '\"': sb.append('\"'); break;      // double quote
                default: sb.append(next); break;        // any other escaped char
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char ch = input.charAt(i);
        if (ch == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            i++; // consume escape character
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '?':
                    sb.append('?');
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 4 < len) {
                        String hex = input.substring(i + 1, i + 5);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 4;
                        } catch (NumberFormatException e) {
                            // Invalid format, keep as literal
                            sb.append('u').append(hex);
                            i += 4;
                        }
                    } else {
                        sb.append('u');
                    }
                    break;
                default:
                    // Octal escape: up to 3 octal digits
                    if (Character.isDigit(next) && next >= '0' && next <= '7') {
                        int octal = next - '0';
                        if (i + 2 < len && input.charAt(i + 2) >= '0' && input.charAt(i + 2) <= '7') {
                            int next2 = input.charAt(i + 2) - '0';
                            if (i + 1 < len && next2 >= 0) {
                                octal = (octal << 3) + next2;
                                if (i + 3 < len && input.charAt(i + 3) >= '0' && input.charAt(i + 3) <= '7') {
                                    int next3 = input.charAt(i + 3) - '0';
                                    octal = (octal << 3) + next3;
                                    i += 2; // consumed two additional digits
                                } else {
                                    i++; // consumed one additional digit
                                }
                            }
                        }
                        sb.append((char) octal);
                    } else {
                        // Unrecognized escape, keep the escaped character as-is
                        sb.append(next);
                    }
                    break;
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

private String unescapeId(String input){
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder sb = new StringBuilder();
    int start = 0;
    int end = input.length() - 1;
    // Strip surrounding quotes if present
    if (input.charAt(0) == '"' && input.charAt(end) == '"') {
        start = 1;
        end = end - 1;
    }
    for (int i = start; i <= end; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 <= end) {
            // Escape sequence: take the next character literally
            sb.append(input.charAt(i + 1));
            i++; // skip next character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

