private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if(bucketsByLabel==null || labels==null) return;
    if(minLabel<0 || minLabel>=bucketsByLabel.size()) return;
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if(source==null || source.isEmpty()) return;
    // Ensure bucket for label 0 exists
    if(bucketsByLabel.size()<=0) return;
    Set<Integer> target = bucketsByLabel.get(0);
    if(target==null){
        target = new HashSet<>();
        // add to list if it's not there
        if(bucketsByLabel.size()>0) bucketsByLabel.set(0, target);
        else bucketsByLabel.add(0, target);
    }
    for(Integer v : source){
        // move vertex to bucket 0
        target.add(v);
        // update label for vertex
        if(v>=0 && v<labels.size()){
            labels.set(v, 0);
        }
    }
    // clear the original bucket
    source.clear();
}

