    for (Object keyObj : map.keySet()){
        if (!(keyObj instanceof String)) continue;
        String key = (String) keyObj;
        try {
            Object value = map.get(key);
            try {
                this.set(key, value);
            } catch (Exception ignored) {
                // ignore properties that cannot be written to
            }
        } catch (Exception ignored) {
            // ignore properties that cannot be read
        }
    }
}

public void putAllWriteable(BeanMap map) {
    for (String key : map.keySet()) {
        // Only copy if the source property is readable and the target property is writable,
        // effectively ignoring read‑only or write‑only properties.
        if (map.isReadable(key) && this.isWritable(key)) {
            Object value = map.get(key);
            this.set(key, value);
        }
    }
}

