public void abbreviate(final int nameStart, final StringBuffer buf) {
    String n = name; // assumes a String field named 'name' in this class
    int len = n.length();
    if (len == 0 || nameStart >= len) {
        return;
    }
    int lastDot = n.lastIndexOf('.', len - 1);
    if (lastDot < 0) {
        lastDot = -1;
    }
    int i = nameStart;
    while (i <= lastDot) {
        if (n.charAt(i) == '.') {
            if (i + 1 < len) {
                buf.append(n.charAt(i + 1));
                buf.append('.');
            }
            i += 2; // skip the dot and the next character
        } else {
            i++;
        }
    }
    int start = Math.max(nameStart, lastDot + 1);
    if (start < len) {
        buf.append(n.substring(start));
    }
}

