    if (nameStart < 0 || nameStart >= name.length()) {
        return;
    }
    String sub = name.substring(nameStart);

    // Generate an abbreviation by taking the first character of each
    // dot‑separated component (e.g., "com.example.MyClass" → "c.e.M").
    String[] parts = sub.split("\\.");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(part.charAt(0));
        }
    }
}

