    Collections.sort(sorted);
    for (Integer keyVal : intKeys){
        int idx = Collections.binarySearch(sorted, keyVal);
        if (idx >= 0){
            // key exists in the list, its lower bound is itself
            lowerBounds.add(keyVal);
        } else {
            int insertPos = -idx - 1;
            if (insertPos == 0){
                // No lower bound exists
                lowerBounds.add(null);
            } else {
                // The element just before the insertion point is the maximum lower bound
                lowerBounds.add(sorted.get(insertPos - 1));
            }
        }
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    // If the descriptor represents a method, pop each argument type from the output frame stack.
    if (descriptor.charAt(0) == '(') {
        int i = 1; // position after '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Determine the size of the next type descriptor.
            int typeLen = 1;
            char c = descriptor.charAt(i);
            if (c == '[') {                // array type
                // Skip all '[' characters
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now i points at the element type; no additional length needed beyond the array brackets.
                typeLen = 1;                // element type will be parsed in the next iteration
            } else if (c == 'L') {           // reference type
                int semicolon = descriptor.indexOf(';', i);
                typeLen = semicolon - i + 1; // include the trailing ';'
            } // for primitive types, typeLen stays 1

            // Pop one value from the output frame stack.
            outputFrameStack.pop();

            // Advance i by the length of the type descriptor just processed.
            i += typeLen;
        }
    } else {
        // For a type descriptor (not a method), simply pop one value.
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int count = 0;
    int i = 0;
    int n = descriptor.length();
    if (descriptor.length() == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        i = 1;
        while (i < n && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                while (i < n && descriptor.charAt(i) == '[') {
                    i++;
                }
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
            count++;
        }
    } else {
        char c = descriptor.charAt(i);
        if (c == '[') {
            while (i < n && descriptor.charAt(i) == '[') {
                i++;
            }
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else {
            i++;
        }
        count++;
    }
    while (count-- > 0) {
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int i = 0;
    while (i < descriptor.length()){
        char c = descriptor.charAt(i);
        if (c == '('){
            i++;
            while (descriptor.charAt(i) != ')'){
                if (descriptor.charAt(i) == 'L'){
                    int semicolon = descriptor.indexOf(';', i);
                    i = semicolon;
                } else if (descriptor.charAt(i) == '['){
                    i++;
                    continue;
                }
                outputFrameStack.pop();
                i++;
            }
            i++; // skip ')'
        } else {
            if (descriptor.charAt(i) == 'L'){
                int semicolon = descriptor.indexOf(';', i);
                i = semicolon;
            } else if (descriptor.charAt(i) == '['){
                i++;
                continue;
            }
            outputFrameStack.pop();
            i++;
        }
    }
}

private void pop(final String descriptor){
    int count = 0;
    int i = 0;
    // Check if descriptor is a method descriptor
    if (descriptor.charAt(i) == '('){
        i++; // skip '('
        while (descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            if (c == '['){
                // Skip array dimensions
                i++;
                continue;
            }
            if (c == 'L'){
                // Object type – pop one abstract type
                count++;
                // Skip to the end of the class name
                i = descriptor.indexOf(';', i) + 1;
            }else{
                // Primitive type – consume one character
                i++;
            }
        }
        // Skip the ')' character
        i++;
        // Ignore the return type
    }else{
        // Descriptor is a single type
        while (descriptor.charAt(i) == '['){
            i++;
        }
        if (descriptor.charAt(i) == 'L'){
            count = 1;
        }
    }
    for (int j = 0; j < count; j++){
        outputStack.pop();
    }
}

private void pop(final String descriptor) {
    // If descriptor is a method descriptor, strip the argument list
    if (descriptor != null && descriptor.startsWith("(")) {
        int close = descriptor.indexOf(')');
        if (close == -1) {
            throw new IllegalArgumentException("Invalid method descriptor");
        }
        descriptor = descriptor.substring(1, close);
    }

    // Iterate over the (possibly shortened) descriptor and pop each type
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);

        // Skip array brackets and treat the base type
        while (c == '[') {
            i++;
            if (i >= descriptor.length()) {
                break;
            }
            c = descriptor.charAt(i);
        }

        // Long and double consume two stack slots
        if (c == 'J' || c == 'D') {
            outputStack.pop();   // high word
            outputStack.pop();   // low word
        } else {
            outputStack.pop();
        }

        // For reference types, consume until the terminating ';'
        if (c == 'L') {
            int end = descriptor.indexOf(';', i);
            if (end == -1) {
                throw new IllegalArgumentException("Invalid descriptor");
            }
            i = end + 1;
        } else {
            i++;
        }
    }
}

