public static String applyRelativePath(String path,String relativePath){
    if(path==null || path.isEmpty()){
        return relativePath==null ? "" : relativePath;
    }
    if(relativePath==null || relativePath.isEmpty()){
        return path;
    }
    boolean isAbsolute = path.startsWith("/");
    java.util.ArrayDeque<String> parts = new java.util.ArrayDeque<>();
    for(String p : path.split("/")){
        if(p.isEmpty()) continue;
        parts.addLast(p);
    }
    for(String r : relativePath.split("/")){
        if(r.isEmpty() || ".".equals(r)) continue;
        if("..".equals(r)){
            if(!parts.isEmpty()){
                parts.removeLast();
            }
        }else{
            parts.addLast(r);
        }
    }
    StringBuilder sb = new StringBuilder();
    if(isAbsolute) sb.append("/");
    java.util.Iterator<String> it = parts.iterator();
    while(it.hasNext()){
        sb.append(it.next());
        if(it.hasNext()){
            sb.append("/");
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    boolean isAbsolute = path != null && path.startsWith("/");
    String[] pathParts = path != null ? path.split("/") : new String[]{};
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    String[] relParts = relativePath != null ? relativePath.split("/") : new String[]{};
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    return result.toString();
}

public static String applyRelativePath(String path,String relativePath){
    String sep="/";
    path=path.replace("\\",sep);
    relativePath=relativePath.replace("\\",sep);
    int lastSep=path.lastIndexOf(sep);
    String base;
    if(lastSep>=0){
        base=path.substring(0,lastSep+1);
    }else{
        base="";
    }
    String joined=base+relativePath;
    String[] parts=joined.split(sep);
    java.util.Deque<String> stack=new java.util.ArrayDeque<>();
    for(String part:parts){
        if(part.isEmpty()||part.equals(".")) continue;
        if(part.equals("..")){
            if(!stack.isEmpty() && !stack.peek().equals("..")){
                stack.pop();
            }else{
                stack.push("..");
            }
        }else{
            stack.push(part);
        }
    }
    java.util.List<String> list=new java.util.ArrayList<>(stack);
    java.util.Collections.reverse(list);
    StringBuilder sb=new StringBuilder();
    boolean absolute=path.startsWith(sep);
    for(String p:list){
        if(absolute||sb.length()>0){
            sb.append(sep);
        }
        sb.append(p);
    }
    if(sb.length()==0) return ".";
    if(!absolute && sb.charAt(0)==sep.charAt(0)){
        sb.deleteCharAt(0);
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if(relativePath==null||relativePath.isEmpty()){
        return path;
    }
    java.nio.file.Path base = java.nio.file.Paths.get(path);
    java.nio.file.Path resolved = base.resolve(relativePath).normalize();
    return resolved.toString().replace(java.io.File.separatorChar,'/');
}

