private void checkIfPackedField() throws IOException {
    // The tag should have been read already from the input stream.
    // Packed fields are encoded as a length‑delimited field that contains
    // a series of packed values.  The wire type for a packed field must
    // be LENGTH_DELIMITED (2) and the field number must match the repeated
    // field that allows packing.  When this condition is satisfied we
    // mark that we are in packed‑field parsing mode so that subsequent
    // reads consume the packed data correctly.
    //
    // If the tag is zero it denotes the end of the input and we simply
    // return without altering any state.  If we are already parsing a
    // packed field and encounter an unexpected tag, we throw an IOException
    // to indicate a protocol violation.

    if (tag == 0) {
        // No more data to read; exit early.
        return;
    }

    int fieldNumber = tag >>> 3;
    int wireType   = tag & 0x7;

    // Wire type 2 means length‑delimited (possible packed data)
    if (wireType == 2 && fieldNumber == packedFieldNumber) {
        // Mark that packed field parsing should commence.
        isReadingPacked = true;
    } else {
        // If we've entered packed mode but encountered a different tag,
        // it's an illegal state for the current protocol.
        if (isReadingPacked) {
            throw new IOException(
                "Expected length‑delimited packed tag but found: 0x"
                + Integer.toHexString(tag));
        }
    }
}

public int readTag() throws IOException {
    // If the underlying input stream is null, we consider it as EOF.
    if (input == null) {
        return 0;
    }
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            // Reached EOF before finding a complete tag.
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
        // Protect against malformed varints that would overflow an int.
        if (shift > 35) {
            throw new IOException("Malformed varint");
        }
    }
}

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = read();
        if (b == -1) {
            return 0; // EOF
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;    // end of varint
        }
        shift += 7;
        if (shift > 35) { // varint too long
            throw new IOException("Malformed tag");
        }
    }
    return tag;
}

